import Config

# Cache manifest with the digested versions of the static files (generated by
# `mix assets.deploy`, which runs before the server starts).
config :{{app}}, {{App}}Web.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# force_ssl is COMPILE-TIME in Phoenix: it is decided when the image is built.
# To deploy over plain HTTP (VPN/LAN with no TLS terminator) build with
# DISABLE_FORCE_SSL=1 and set PHX_SCHEME=http at runtime.
# (The skeleton default is HTTPS; see SPEC-docker.md §Hard rules.)
#
# `rewrite_on: [:x_forwarded_proto]` is the only part that cannot move to
# runtime: Plug.SSL compares `conn.scheme` when it runs, which is before the
# endpoint's own plugs, so the header has to be honored here for a TLS
# terminating proxy not to bounce every request. It is safe because it only
# affects the redirect decision of that request (a client claiming `https` over
# plain HTTP skips a redirect it was going to get anyway).
#
# Trusting the OTHER X-Forwarded-* headers (client IP, host, port) is a separate,
# runtime decision: TRUST_PROXY=1 in config/runtime.exs drives the endpoint's
# Plug.RewriteOn MFA. Leave it off unless the container is unreachable except
# through the proxy and the proxy strips those headers — see SPEC-docker.md
# §Proxy trust.
if System.get_env("DISABLE_FORCE_SSL") != "1" do
  config :{{app}}, {{App}}Web.Endpoint,
    force_ssl: [
      rewrite_on: [:x_forwarded_proto],
      # Exclude ONLY liveness: a client-controlled Host header must not bypass
      # HTTPS/HSTS for the rest of the app. `/ready` remains HTTPS at the proxy.
      exclude: [paths: ["/health"]]
    ]
end

# Swoosh's HTTP client.
config :swoosh, api_client: Swoosh.ApiClient.Req

# Swoosh does not keep mail in memory in prod.
config :swoosh, local: false

# No debug noise in production.
config :logger, level: :info

# Runtime configuration (environment variables) lives in config/runtime.exs.
